// Offline reconciliation: extract the acquired archive and prove it blob-for-blob against
// the recursive git tree at the pinned revision. No network. Writes reconciliation.json.
const fs = require('node:fs');
const cp = require('node:child_process');
const crypto = require('node:crypto');
const path = require('node:path');

const D = 'evidence/ingests/angular-factoriolab';
const CACHE = '.versionless/cache/angular-factoriolab-source';
const OUT = `${CACHE}/verify/extracted`;
const ROOT = 'factoriolab-5f54abbdcac518d8ebf7e136c4348384d9b1a2bb';

const gitBlob = (b) =>
	crypto
		.createHash('sha1')
		.update(Buffer.concat([Buffer.from(`blob ${b.length}\0`), b]))
		.digest('hex');

const listing = cp
	.execFileSync('tar', ['-tzvf', `${CACHE}/archive/archive-1.tar.gz`], { maxBuffer: 1 << 28 })
	.toString()
	.trim()
	.split('\n');
const roots = new Set();
let dirs = 0;
let files = 0;
let special = 0;
let traversal = 0;
let absolute = 0;
for (const line of listing) {
	const kind = line[0];
	const name = line.slice(line.indexOf(ROOT.slice(0, 6)) >= 0 ? 0 : 0).replace(/^.*?\s(\S+)$/, '$1');
	const p = line.split(/\s+/).slice(5).join(' ');
	roots.add(p.split('/')[0]);
	if (p.startsWith('/')) absolute += 1;
	if (p.split('/').includes('..')) traversal += 1;
	if (kind === 'd') dirs += 1;
	else if (kind === '-') files += 1;
	else special += 1;
	void name;
}

fs.rmSync(`${CACHE}/verify`, { recursive: true, force: true });
fs.mkdirSync(OUT, { recursive: true });
cp.execFileSync('tar', ['-xzf', `${CACHE}/archive/archive-1.tar.gz`, '--strip-components=1', '-C', OUT]);

const tree = JSON.parse(fs.readFileSync(`${D}/probe-tree.json`, 'utf8'));
const treeBlobs = new Map();
for (const e of tree.tree) if (e.type === 'blob') treeBlobs.set(e.path, e.sha);

const seen = [];
const walk = (dir, prefix) => {
	for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
		const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
		if (entry.isDirectory()) walk(path.join(dir, entry.name), rel);
		else if (entry.isFile()) seen.push(rel);
	}
};
walk(OUT, '');

let mismatched = 0;
const missing = [];
const extra = [];
const manifest = [];
for (const rel of seen.sort()) {
	const buf = fs.readFileSync(path.join(OUT, rel));
	const blob = gitBlob(buf);
	manifest.push(`${blob}  ${rel}`);
	const expected = treeBlobs.get(rel);
	if (!expected) extra.push(rel);
	else if (expected !== blob) mismatched += 1;
}
for (const p of treeBlobs.keys()) if (!seen.includes(p)) missing.push(p);

const normalizedManifestSha256 = crypto
	.createHash('sha256')
	.update(`${manifest.join('\n')}\n`)
	.digest('hex');

const record = {
	schemaVersion: 'versionless.legacy-corpus-reconciliation.v1',
	slug: 'angular-factoriolab',
	method:
		'Every regular file in the extracted archive was hashed as a git blob object and compared byte-for-byte against the sha recorded for the same path in the recursive git tree at the pinned revision.',
	singleRoot: [...roots][0],
	rootCount: roots.size,
	archiveEntries: listing.length,
	directories: dirs,
	regularFiles: files,
	specialEntries: special,
	pathTraversalEntries: traversal,
	absolutePathEntries: absolute,
	gitBlobs: treeBlobs.size,
	extractedFiles: seen.length,
	missingFiles: missing.length,
	extraFiles: extra.length,
	mismatchedBlobs: mismatched,
	missing,
	extra,
	normalizedManifestSha256,
	archiveMatchesGitTree: missing.length === 0 && extra.length === 0 && mismatched === 0,
};
fs.writeFileSync(`${D}/reconciliation.json`, `${JSON.stringify(record, null, 2)}\n`);
fs.appendFileSync(
	`${D}/transcript.ndjson`,
	`${JSON.stringify({
		at: new Date().toISOString(),
		step: 'reconcile-archive-against-git-tree',
		runner: 'node evidence/ingests/angular-factoriolab/scripts/reconcile.cjs',
		network: 'none',
		wrote: [`${D}/reconciliation.json`],
	})}\n`,
);
console.log(JSON.stringify(record, null, 1));

