// Baseline attempt: `npm ci` then the upstream production build (`npm run build -- --prod`)
// in the declared legacy cell (Node 12.14.1 darwin-x64 under Rosetta 2, npm 6.13.4).
// Package-manager network traffic (registry.npmjs.org) is covered by the baseline clause of
// consent VL-LEGACY-CORPUS-2026-08-10. Angular CLI analytics is disabled so the build
// contacts nothing beyond the package manager. Logs stay in the git-ignored cache.
const fs = require('node:fs');
const cp = require('node:child_process');
const path = require('node:path');

const SRC = '.versionless/cache/angular-factoriolab-source/verify/extracted';
const BASE = '.versionless/cache/angular-factoriolab-baseline';
const APP = `${BASE}/app`;
const NODE_HOME = process.env.LEGACY_NODE_HOME;
if (!NODE_HOME) throw new Error('LEGACY_NODE_HOME is required');

fs.rmSync(BASE, { recursive: true, force: true });
fs.mkdirSync(APP, { recursive: true });
cp.execFileSync('cp', ['-R', `${SRC}/.`, APP]);

const env = {
	...process.env,
	PATH: `${path.join(NODE_HOME, 'bin')}:${process.env.PATH ?? ''}`,
	npm_config_cache: `${process.cwd()}/${BASE}/npm-cache`,
	NPM_CONFIG_CACHE: `${process.cwd()}/${BASE}/npm-cache`,
	NG_CLI_ANALYTICS: 'false',
	CI: '',
};

function phase(name, args) {
	const started = Date.now();
	const r = cp.spawnSync(path.join(NODE_HOME, 'bin/npm'), args, {
		cwd: APP,
		env,
		encoding: 'utf8',
		maxBuffer: 1 << 28,
	});
	fs.writeFileSync(`${BASE}/${name}.stdout.log`, r.stdout ?? '');
	fs.writeFileSync(`${BASE}/${name}.stderr.log`, r.stderr ?? '');
	return { name, args, status: r.status, durationMs: Date.now() - started };
}

const results = [];
results.push(phase('install', ['ci', '--no-audit', '--no-fund']));
if (results[0].status === 0)
	results.push(phase('build', ['run', 'build', '--', '--prod']));
fs.writeFileSync(`${BASE}/phases.json`, `${JSON.stringify(results, null, 2)}\n`);
console.log(JSON.stringify(results, null, 1));

