// Labeled DEVIATION (not the baseline): the codeload archive at the pinned revision carries
// Git LFS pointer stubs for src/data/** and *.png. This fetches the LFS payloads over plain
// GET from media.githubusercontent.com at the same pinned revision, verifies each payload
// against the sha256 oid recorded in the pointer it replaces (so integrity is proven by the
// pinned git content itself, not by trust in the media host), materialises them into the
// baseline working tree, and re-runs the production build.
// Consent: VL-LEGACY-CORPUS-2026-08-10, acquisition purpose. GET only, no credentials.
const fs = require('node:fs');
const https = require('node:https');
const crypto = require('node:crypto');
const cp = require('node:child_process');
const path = require('node:path');

const D = 'evidence/ingests/angular-factoriolab';
const BASE = '.versionless/cache/angular-factoriolab-baseline';
const APP = `${BASE}/app`;
const SRC = '.versionless/cache/angular-factoriolab-source/verify/extracted';
const REPO = 'factoriolab/factoriolab';
const PIN = '5f54abbdcac518d8ebf7e136c4348384d9b1a2bb';
const NODE_HOME = process.env.LEGACY_NODE_HOME;

const sha = (b) => crypto.createHash('sha256').update(b).digest('hex');
function get(url, redirects = 0) {
	return new Promise((resolve, reject) => {
		const u = new URL(url);
		https
			.get(
				{
					hostname: u.hostname,
					path: u.pathname + u.search,
					headers: { 'user-agent': 'versionless-legacy-corpus', 'accept-encoding': 'identity' },
				},
				(r) => {
					if (r.statusCode >= 300 && r.statusCode < 400 && r.headers.location && redirects < 3) {
						r.resume();
						resolve(get(new URL(r.headers.location, url).toString(), redirects + 1));
						return;
					}
					const c = [];
					r.on('data', (d) => c.push(d));
					r.on('end', () => resolve({ s: r.statusCode, b: Buffer.concat(c), redirects }));
				},
			)
			.on('error', reject);
	});
}

const walk = (dir, prefix, out) => {
	for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
		const rel = prefix ? `${prefix}/${e.name}` : e.name;
		if (e.isDirectory()) walk(path.join(dir, e.name), rel, out);
		else if (e.isFile()) out.push(rel);
	}
	return out;
};

(async () => {
	if (
		process.env.VERSIONLESS_NETWORK_MODE !== 'consented' ||
		process.env.VERSIONLESS_CONSENT_ID !== 'VL-LEGACY-CORPUS-2026-08-10'
	)
		throw new Error('consent gate closed');
	const pointers = [];
	for (const rel of walk(SRC, '', [])) {
		const buf = fs.readFileSync(path.join(SRC, rel));
		if (buf.length > 200 || !buf.slice(0, 40).toString().startsWith('version https://git-lfs.github.com/spec/v1'))
			continue;
		const text = buf.toString();
		const oid = /oid sha256:([0-9a-f]{64})/.exec(text);
		const size = /size (\d+)/.exec(text);
		if (!oid || !size) throw new Error(`unparsable pointer: ${rel}`);
		pointers.push({ path: rel, oid: oid[1], size: Number(size[1]), pointerSha256: sha(buf) });
	}
	const led = [];
	let bytes = 0;
	for (const p of pointers) {
		const url = `https://media.githubusercontent.com/media/${REPO}/${PIN}/${p.path}`;
		const r = await get(url);
		if (r.s !== 200) throw new Error(`${p.path}: status ${r.s}`);
		const got = sha(r.b);
		p.fetchedSha256 = got;
		p.fetchedBytes = r.b.length;
		p.oidVerified = got === p.oid && r.b.length === p.size;
		bytes += r.b.length;
		led.push({
			at: new Date().toISOString(),
			phase: 'lfs-payload-materialisation',
			method: 'GET',
			url,
			status: r.s,
			bytes: r.b.length,
			sha256: got,
			matchesPointerOid: p.oidVerified,
			redirectsFollowed: r.redirects,
		});
		if (!p.oidVerified) throw new Error(`${p.path}: payload does not match pointer oid`);
		fs.writeFileSync(path.join(APP, p.path), r.b);
	}
	fs.appendFileSync(`${D}/probe-ledger.ndjson`, `${led.map((x) => JSON.stringify(x)).join('\n')}\n`);
	fs.appendFileSync(
		`${D}/transcript.ndjson`,
		`${JSON.stringify({
			at: new Date().toISOString(),
			step: 'lfs-deviation-materialise-and-rebuild',
			runner: 'node evidence/ingests/angular-factoriolab/scripts/lfs-deviation.cjs',
			consentId: process.env.VERSIONLESS_CONSENT_ID,
			networkMode: process.env.VERSIONLESS_NETWORK_MODE,
			wrote: [`${D}/probe-ledger.ndjson`, `${D}/lfs.json`, `${APP}/src/data`, `${APP}/src/assets`],
		})}\n`,
	);
	const env = {
		...process.env,
		PATH: `${path.join(NODE_HOME, 'bin')}:${process.env.PATH ?? ''}`,
		npm_config_cache: `${process.cwd()}/${BASE}/npm-cache`,
		NG_CLI_ANALYTICS: 'false',
	};
	const started = Date.now();
	const r = cp.spawnSync(path.join(NODE_HOME, 'bin/npm'), ['run', 'build', '--', '--prod'], {
		cwd: APP,
		env,
		encoding: 'utf8',
		maxBuffer: 1 << 28,
	});
	fs.writeFileSync(`${BASE}/deviation-build.stdout.log`, r.stdout ?? '');
	fs.writeFileSync(`${BASE}/deviation-build.stderr.log`, r.stderr ?? '');
	const distExists = fs.existsSync(`${APP}/dist`);
	const dist = distExists ? walk(`${APP}/dist`, '', []) : [];
	const record = {
		pointerFiles: pointers.length,
		fetchedBytes: bytes,
		allOidsVerified: pointers.every((p) => p.oidVerified),
		pointers,
		buildExitStatus: r.status,
		buildDurationMs: Date.now() - started,
		distFiles: dist.length,
		distBytes: dist.reduce((s, f) => s + fs.statSync(`${APP}/dist/${f}`).size, 0),
	};
	fs.writeFileSync(`${D}/lfs.json`, `${JSON.stringify(record, null, 2)}\n`);
	console.log(
		JSON.stringify(
			{ ...record, pointers: undefined, distSample: dist.slice(0, 12) },
			null,
			1,
		),
	);
})();

